struct CounterView: View {
    @State private var count = 0           // source of truth

    var body: some View {                  // UI = f(count)
        VStack(spacing: 12) {
            Text("Count: \(count)")
                .font(.title)
            Button("Add") { count += 1 }   // change state, not the label
        }
        .padding()
    }
}
